34	export class Rocket
35	  extends SceneObject<RocketTweenProps>
36	  implements RocketPort
37	{
38	  private _model: THREE.Group | null = null;
39	  private _options: Partial<RocketObjectOptions> = {};
40	  private _flameMesh: THREE.Mesh<
41	    THREE.PlaneGeometry,
42	    THREE.ShaderMaterial
43	  > | null = null;
44	  private _flameAnchor: THREE.Object3D | null = null;
45	  private _hasLoggedFlameAnchorDebug = false;
46	  private readonly _modelBounds = new THREE.Box3();
47	  private readonly _modelBoundsCenter = new THREE.Vector3();
48	  private readonly _cameraWorldQuaternion = new THREE.Quaternion();
49	  private readonly _rootWorldQuaternion = new THREE.Quaternion();
50	  private readonly _flameLocalQuaternion = new THREE.Quaternion();
51	  private readonly _flameLocalEuler = new THREE.Euler();
52	  private readonly _anchorLocalPosition = new THREE.Vector3();
53	  private readonly _flamePositionScratch = new THREE.Vector3();
54	  private readonly _flameRotationScratch: { x: number; y: number; z: number } = {
55	    x: 0,
56	    y: 0,
57	    z: 0,
58	  };
59	
60	  setOptions(props: Partial<RocketObjectOptions> | undefined): this {
61	    if (props != null) this._options = { ...this._options, ...props };
62	    return this;
63	  }
64	
65	  protected override getOptions(): Record<string, unknown> {
66	    return this._options;
67	  }
68	
69	  protected override isAlwaysVisible(): boolean {
70	    return true;
71	  }
72	
73	  protected override applyVisibility(_visible: boolean): void {
74	    const root = this.getTimelineRoot();
75	    if (root) root.visible = true;
76	  }
77	
78	  protected override syncFromOptions(): void {
79	    this._syncTransform();
80	    const root = this.getTimelineRoot();
81	    if (!root) return;
82	    this._applyMaterialVisibilityBoost(root);
83	    if (!this._flameMesh && this._model) {
84	      this._buildFlame();
85	    }
86	    this._syncFlameState(root);
87	  }
