97	  override async runObject(): Promise<void> {
98	    const ctx = this._context;
99	    if (!ctx) return;
100	
101	    const modelUrl = this._options.modelUrl;
102	    if (!modelUrl) {
103	      Logger.error(
104	        ROCKET_CLASS,
105	        "runObject",
106	        "Rocket modelUrl must be defined in object.config.ts.",
107	      );
108	      return;
109	    }
110	
111	    try {
112	      const model = await ctx.loadModel(this.resolveAssetPath(modelUrl));
113	      const group = model as THREE.Group;
114	      this._model = group;
115	      this.attachToTimelineRoot(group, "rocketRoot");
116	      this._flameAnchor = this._resolveFlameAnchor(group);
117	      this._logFlameAnchorDebug(group, this._flameAnchor);
118	      this._syncTransform();
119	      this._applyMaterialVisibilityBoost(group);
120	      this._buildFlame();
121	      this._syncFlameState(this.getTimelineRoot());
122	    } catch (error) {
123	      Logger.error(
124	        ROCKET_CLASS,
125	        "runObject",
126	        "Failed to load rocket model.",
127	        error,
128	      );
129	    }
130	  }
131	
132	  override runUpdate(_delta: number): void {
133	    this._syncFlameBillboard();
134	  }
135	
136	  override dispose(): void {
137	    this.releaseShaders(this.getShaderOwnerId());
138	    this._disposeFlame();
139	    if (this._model) {
140	      this._model.traverse((child) => {
141	        if ((child as THREE.Mesh).isMesh) {
142	          const mesh = child as THREE.Mesh;
143	          mesh.geometry?.dispose();
144	          const materials = Array.isArray(mesh.material)
145	            ? mesh.material
146	            : [mesh.material];
147	          for (const material of materials) {
148	            (material as THREE.Material)?.dispose?.();
149	          }
150	        }
151	      });
152	    }
153	    this._model = null;
154	    this._flameAnchor = null;
155	    super.dispose();
156	  }
157	
158	  setFlameState(state: RocketFlameStateSnapshot): void {
159	    this._options.flame = {
160	      ...(this._options.flame ?? {}),
161	      visible: state.visible,
162	      offset: { ...state.offset },
163	      rotation: { ...state.rotation },
164	      scale: { ...state.scale },
165	      opacity: state.opacity,
166	      renderOrder: state.renderOrder,
167	      speed: state.speed,
168	      wave: state.wave,
169	    };
170	    if (!this._flameMesh && this._model) {
171	      this._buildFlame();
172	    }
173	    this._syncFlameState(this.getTimelineRoot());
174	  }
175	
176	  getFlameState(): RocketFlameStateSnapshot {
177	    const flameOptions = this._resolveFlameOptions();
178	    const offset = flameOptions.offset ?? DEFAULT_FLAME_OFFSET;
179	    const rotation = flameOptions.rotation ?? DEFAULT_FLAME_ROTATION;
180	    const scale = flameOptions.scale ?? DEFAULT_FLAME_SCALE;
181	    return {
182	      visible: flameOptions.visible !== false,
183	      offset: {
184	        x: offset.x ?? DEFAULT_FLAME_OFFSET.x,
185	        y: offset.y ?? DEFAULT_FLAME_OFFSET.y,
186	        z: offset.z ?? DEFAULT_FLAME_OFFSET.z,
187	      },
188	      rotation: {
189	        x: rotation.x ?? DEFAULT_FLAME_ROTATION.x,
190	        y: rotation.y ?? DEFAULT_FLAME_ROTATION.y,
191	        z: rotation.z ?? DEFAULT_FLAME_ROTATION.z,
192	      },
193	      scale: {
194	        x: scale.x ?? DEFAULT_FLAME_SCALE.x,
195	        y: scale.y ?? DEFAULT_FLAME_SCALE.y,
196	        z: scale.z ?? DEFAULT_FLAME_SCALE.z,
197	      },
198	      opacity: this._resolveFlameOpacity(flameOptions),
199	      renderOrder: this._resolveFlameRenderOrder(flameOptions),
200	      speed: this._resolveFlameSpeed(flameOptions),
201	      wave: this._resolveFlameWave(flameOptions),
202	    };
203	  }
204	
205	  private _applyMaterialVisibilityBoost(group: THREE.Group): void {
206	    const emissiveIntensity = Number.isFinite(
207	      this._options.emissiveIntensity as number,
208	    )
209	      ? Number(this._options.emissiveIntensity)
210	      : 0;
211	    const emissiveColor = Number.isFinite(this._options.emissiveColor as number)
212	      ? Number(this._options.emissiveColor)
213	      : 0;
214	    const color = new THREE.Color(emissiveColor);
215	
216	    group.traverse((child) => {
217	      if (!(child as THREE.Mesh).isMesh) return;
218	      const mesh = child as THREE.Mesh;
219	      const materials = Array.isArray(mesh.material)
220	        ? mesh.material
221	        : [mesh.material];
222	      for (const material of materials) {
223	        if (!material) continue;
224	        const target = material as {
225	          emissive?: THREE.Color;
226	          emissiveIntensity?: number;
227	          needsUpdate?: boolean;
228	        };
229	        if (!(target.emissive instanceof THREE.Color)) continue;
230	        target.emissive.copy(color);
231	        target.emissiveIntensity = emissiveIntensity;
232	        if (typeof target.needsUpdate === "boolean") {
233	          target.needsUpdate = true;
234	        }
235	      }
236	    });
237	  }
238	
239	  private _syncTransform(): void {
240	    const root = this.getTimelineRoot();
241	    if (!root) return;
242	    Helpers.applyTransform(root, this._options);
243	    root.traverse((child) => {
244	      child.layers.set(THREE_LAYER_ROCKET);
245	    });
246	  }
247	
248	  private _buildFlame(): void {
249	    const root = this.getTimelineRoot();
250	    const model = this._model;
251	    if (!root || !model) return;
252	
253	    this._disposeFlame();
254	    this._modelBounds.setFromObject(model);
255	    const flameOptions = this._resolveFlameOptions();
256	    if (flameOptions.visible === false) return;
257	
258	    const material = new THREE.ShaderMaterial({
259	      uniforms: {
260	        iTime: { value: 0 },
261	        iResolution: { value: new THREE.Vector2(512, 1024) },
262	        uOpacity: { value: this._resolveFlameOpacity(flameOptions) },
263	        uFlameSpeed: { value: this._resolveFlameSpeed(flameOptions) },
264	        uWaveStrength: { value: this._resolveFlameWave(flameOptions) },
265	      },
266	      vertexShader: flameVertexShader as string,
267	      fragmentShader: flameFragmentShader as string,
268	      transparent: true,
269	      depthWrite: false,
270	      depthTest: true,
271	      blending: THREE.AdditiveBlending,
272	      side: THREE.DoubleSide,
273	    });
274	
275	    this.registerShader({
276	      key: this.createShaderKey(ROCKET_FLAME_SHADER_KEY),
277	      ownerId: this.getShaderOwnerId(),
278	      material,
279	    });
280	
281	    const geometry = new THREE.PlaneGeometry(1, 1, 1, 1);
282	    geometry.translate(0, -0.5, 0);
283	    const mesh = new THREE.Mesh(geometry, material);
284	    mesh.layers.set(THREE_LAYER_ROCKET);
285	    mesh.renderOrder = this._resolveFlameRenderOrder(flameOptions);
286	    const anchor = this._flameAnchor;
287	    if (anchor) {
288	      anchor.add(mesh);
289	    } else {
290	      root.add(mesh);
291	    }
292	    this._flameMesh = mesh;
293	  }
294	
295	  private _disposeFlame(): void {
296	    const flameMesh = this._flameMesh;
297	    if (!flameMesh) return;
298	    flameMesh.parent?.remove(flameMesh);
299	    flameMesh.geometry.dispose();
300	    flameMesh.material.dispose();
301	    this._flameMesh = null;
302	  }
303	
304	  private _syncFlameState(root: THREE.Object3D | null): void {
305	    const flameMesh = this._flameMesh;
306	    if (!root || !flameMesh) return;
307	    const flameOptions = this._resolveFlameOptions();
308	    const flameScale = flameOptions.scale ?? DEFAULT_FLAME_SCALE;
309	    const flameOffset = flameOptions.offset ?? DEFAULT_FLAME_OFFSET;
310	    const anchor = this._flameAnchor;
311	    if (anchor && flameMesh.parent !== anchor) {
312	      anchor.add(flameMesh);
313	    } else if (!anchor && flameMesh.parent !== root) {
314	      root.add(flameMesh);
315	    }
316	
317	    flameMesh.visible = flameOptions.visible !== false && root.visible;
318	    if (anchor && flameMesh.parent === anchor) {
319	      const ox = flameOffset?.x ?? DEFAULT_FLAME_OFFSET.x;
320	      const oy = flameOffset?.y ?? DEFAULT_FLAME_OFFSET.y;
321	      const oz = flameOffset?.z ?? DEFAULT_FLAME_OFFSET.z;
322	      flameMesh.position.set(ox, oy, oz);
323	    } else {
324	      const flamePosition = this._resolveFlamePosition(flameOffset);
325	      flameMesh.position.set(flamePosition.x, flamePosition.y, flamePosition.z);
326	    }
327	    flameMesh.scale.set(
328	      flameScale.x ?? DEFAULT_FLAME_SCALE.x,
329	      flameScale.y ?? DEFAULT_FLAME_SCALE.y,
330	      flameScale.z ?? DEFAULT_FLAME_SCALE.z,
331	    );
332	    flameMesh.renderOrder = this._resolveFlameRenderOrder(flameOptions);
333	    flameMesh.material.uniforms.uOpacity.value =
334	      this._resolveFlameOpacity(flameOptions);
335	    flameMesh.material.uniforms.uFlameSpeed.value =
336	      this._resolveFlameSpeed(flameOptions);
337	    flameMesh.material.uniforms.uWaveStrength.value =
338	      this._resolveFlameWave(flameOptions);
339	    this._syncFlameBillboard();
340	  }
341	
342	  private _syncFlameBillboard(): void {
343	    const root = this.getTimelineRoot();
344	    const flameMesh = this._flameMesh;
345	    const camera = this._context?.camera;
346	    if (!root || !flameMesh || !camera) return;
347	
348	    camera.getWorldQuaternion(this._cameraWorldQuaternion);
349	    root.getWorldQuaternion(this._rootWorldQuaternion);
350	    this._rootWorldQuaternion.invert();
351	    flameMesh.quaternion
352	      .copy(this._rootWorldQuaternion)
353	      .multiply(this._cameraWorldQuaternion);
354	    const flameRotation = this._resolveFlameRotation(
355	      this._resolveFlameOptions(),
356	    );
357	    this._flameLocalEuler.set(
358	      THREE.MathUtils.degToRad(flameRotation.x),
359	      THREE.MathUtils.degToRad(flameRotation.y),
360	      THREE.MathUtils.degToRad(flameRotation.z),
361	    );
362	    this._flameLocalQuaternion.setFromEuler(this._flameLocalEuler);
363	    flameMesh.quaternion.multiply(this._flameLocalQuaternion);
364	  }
365	
366	  private _resolveFlameOptions(): RocketFlameOptions {
367	    return this._options.flame ?? {};
368	  }
369	
370	  private _resolveFlameAnchor(model: THREE.Group): THREE.Object3D | null {
371	    const flameOptions = this._resolveFlameOptions();
372	    const explicitAnchor = this._findExplicitFlameAnchor(model, flameOptions);
373	    if (explicitAnchor) return explicitAnchor;
374	    return this._findHeuristicFlameAnchor(model, flameOptions);
375	  }
376	
377	  private _findExplicitFlameAnchor(
378	    model: THREE.Group,
379	    options: RocketFlameOptions,
380	  ): THREE.Object3D | null {
381	    const anchorName = options.anchorName?.trim();
382	    if (!anchorName) return null;
383	    const target = model.getObjectByName(anchorName);
384	    if (!target) {
385	      Logger.warn(
386	        ROCKET_CLASS,
387	        "runObject",
388	        `Rocket flame anchor "${anchorName}" was not found. Falling back to heuristics.`,
389	      );
390	      return null;
391	    }
392	    return target;
393	  }
394	
395	  private _findHeuristicFlameAnchor(
396	    model: THREE.Group,
397	    options: RocketFlameOptions,
398	  ): THREE.Object3D | null {
399	    const normalizedIncludes = this._getNormalizedFlameAnchorIncludes(options);
400	    let bestMatch: THREE.Object3D | null = null;
401	
402	    model.traverse((child) => {
403	      if (bestMatch || child === model) return;
404	      const normalizedName = child.name.trim().toLowerCase();
405	      if (!normalizedName) return;
406	      if (!normalizedIncludes.some((value) => normalizedName.includes(value)))
407	        return;
408	      bestMatch = child;
409	    });
410	
411	    if (!bestMatch) {
412	      Logger.warn(
413	        ROCKET_CLASS,
414	        "runObject",
415	        "Rocket flame anchor was not found by name. Falling back to bounding-box placement.",
416	      );
417	    }
418	
419	    return bestMatch;
420	  }
421	
422	  private _logFlameAnchorDebug(
423	    model: THREE.Group,
424	    anchor: THREE.Object3D | null,
425	  ): void {
426	    if (this._hasLoggedFlameAnchorDebug) return;
427	    if (!EnvSetup.hasQueryFlag("theatre", "1")) return;
428	    this._hasLoggedFlameAnchorDebug = true;
429	
430	    const flameOptions = this._resolveFlameOptions();
431	    const normalizedIncludes =
432	      this._getNormalizedFlameAnchorIncludes(flameOptions);
433	    const allNodeNames: string[] = [];
434	    const candidateNodeNames: string[] = [];
435	
436	    model.traverse((child) => {
437	      if (child === model) return;
438	      const nodeName = child.name.trim();
439	      if (!nodeName) return;
440	      allNodeNames.push(nodeName);
441	      const normalizedName = nodeName.toLowerCase();
442	      if (!normalizedIncludes.some((value) => normalizedName.includes(value)))
443	        return;
444	      candidateNodeNames.push(nodeName);
445	    });
446	
447	  }
448	
449	  private _getNormalizedFlameAnchorIncludes(
450	    options: RocketFlameOptions,
451	  ): string[] {
452	    const includes = options.anchorNameIncludes?.length
453	      ? options.anchorNameIncludes
454	      : [...DEFAULT_FLAME_ANCHOR_NAME_INCLUDES];
455	    return includes.map((value) => value.toLowerCase());
456	  }
457	
458	  private _resolveFlamePosition(
459	    offset: RocketFlameOptions["offset"],
460	  ): THREE.Vector3 {
461	    const x = offset?.x ?? DEFAULT_FLAME_OFFSET.x;
462	    const y = offset?.y ?? DEFAULT_FLAME_OFFSET.y;
463	    const z = offset?.z ?? DEFAULT_FLAME_OFFSET.z;
464	    const anchor = this._flameAnchor;
465	    const model = this._model;
466	    const out = this._flamePositionScratch;
467	    if (!anchor || !model) {
468	      this._modelBounds.getCenter(this._modelBoundsCenter);
469	      out.set(
470	        this._modelBoundsCenter.x + x,
471	        this._modelBounds.min.y + y,
472	        this._modelBoundsCenter.z + z,
473	      );
474	      return out;
475	    }
476	
477	    anchor.getWorldPosition(this._anchorLocalPosition);
478	    model.worldToLocal(this._anchorLocalPosition);
479	    out.set(
480	      this._anchorLocalPosition.x + x,
481	      this._anchorLocalPosition.y + y,
482	      this._anchorLocalPosition.z + z,
483	    );
484	    return out;
485	  }
486	
487	  private _resolveFlameOpacity(options: RocketFlameOptions): number {
488	    return Number.isFinite(options.opacity as number)
489	      ? Number(options.opacity)
490	      : DEFAULT_FLAME_OPACITY;
491	  }
492	
493	  private _resolveFlameRotation(
494	    options: RocketFlameOptions,
495	  ): Required<RocketFlameStateSnapshot>["rotation"] {
496	    const rotation = options.rotation ?? DEFAULT_FLAME_ROTATION;
497	    const out = this._flameRotationScratch;
498	    out.x = Number.isFinite(rotation.x as number)
499	      ? Number(rotation.x)
500	      : DEFAULT_FLAME_ROTATION.x;
501	    out.y = Number.isFinite(rotation.y as number)
502	      ? Number(rotation.y)
503	      : DEFAULT_FLAME_ROTATION.y;
504	    out.z = Number.isFinite(rotation.z as number)
505	      ? Number(rotation.z)
506	      : DEFAULT_FLAME_ROTATION.z;
507	    return out;
508	  }
509	
510	  private _resolveFlameRenderOrder(options: RocketFlameOptions): number {
511	    return Number.isFinite(options.renderOrder as number)
512	      ? Math.round(Number(options.renderOrder))
513	      : DEFAULT_FLAME_RENDER_ORDER;
514	  }
515	
516	  private _resolveFlameSpeed(options: RocketFlameOptions): number {
517	    return Number.isFinite(options.speed as number)
518	      ? Number(options.speed)
519	      : DEFAULT_FLAME_SPEED;
520	  }
521	
522	  private _resolveFlameWave(options: RocketFlameOptions): number {
523	    return Number.isFinite(options.wave as number)
524	      ? Number(options.wave)
525	      : DEFAULT_FLAME_WAVE;
526	  }
527	
528	}
